import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalise, collapseSpaces } from '../src/normalise.mjs';

test('trims every line, not only the last', () => {
  assert.equal(normalise('a  \nb\t\nc'), 'a\nb\nc');
});

test('leaves clean input alone', () => {
  assert.equal(normalise('a\nb'), 'a\nb');
});

test('collapseSpaces collapses runs of spaces to one', () => {
  assert.equal(collapseSpaces('a   b    c'), 'a b c');
});

test('collapseSpaces leaves input with no repeated spaces alone', () => {
  assert.equal(collapseSpaces('a b c'), 'a b c');
});

test('collapseSpaces does not touch tabs or newlines', () => {
  assert.equal(collapseSpaces('a\t\tb\nc'), 'a\t\tb\nc');
});

